import { Container, Button, CustomText } from '../../../../../../components'
import { LANG_STRINGS, ERROR_LANG } from '../../../../../../lang'
import DynamicForm from '../../../../../../components/DynamicForm'
import { AddBankWrapper, Footer } from './index.style'
import { useGlobalContextValue } from '../../../../../../contextProvider/GlobalContext'
import { useShowAgentPIC } from '../../../../../../state/globalState/hooks/useGlobalContext'
import { useGetBankList } from '../../../../Withdrawal/state/hooks/useWithdraw'
import { useUpdateBankAccounts, useGetBankAccountDetails } from '../../BankAccount/state/hooks/useBankAccounts'
import { useEffect, useCallback, useState, useRef, useMemo } from 'react'
import { useHistory } from 'react-router'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
// import BottomSheetUpload from '../../BankAccount/components/BottomSheetUpload'
import BottomSheetVerify from '../../BankAccount/components/BottomSheetVerify'

function AddBankForm () {
  const [{ getAgentDetailData = {} }] = useGlobalContextValue()
  const [bankLists, getBankListRequest] = useGetBankList()
  const [{ updateBankAccountData = {} }, updateBankAccountRequest] = useUpdateBankAccounts()
  const [bankAccountData, getBankAccountDetailsRequest] = useGetBankAccountDetails()
  const [showText, setShowText] = useState(false)
  const [bankCode, setBankID] = useState('')
  const [accountNumber, setAccountNumber] = useState('')
  const [repeatAccountNumber, setRepeatAccountNumber] = useState('')
  const [showBottom, setShowBottom] = useState(false)
  const formRef = useRef()
  const [, setShowAgentPIC] = useShowAgentPIC()
  const history = useHistory()
  const [{ updateBankAccountStatus, updateBankAccountErrorData, getBankAccountDetailsStatus, getBankAccountDetailsErrorData }] = useErrorContextValue()
  const { resetError } = useResetError()
  const [{ GET_BANK_ACCOUNT_DETAILS_LOADER }] = useLoaderContextValue()

  useEffect(() => {
    getBankListRequest()
  }, [getBankListRequest])

  useEffect(() => {
    // if (updateBankAccountStatus === 'success') {
    //   setToLocalStorage(BANK_FORM_DATA, {
    //     operation_id: updateBankAccountData?.operation_id,
    //     bank_id: updateBankAccountData?.bank_id
    //   })
    //   history.push('/bank-otp')
    //   resetError(['updateBankAccountStatus'])
    // }
    // if (updateBankAccountErrorData) {
    //   ShowSnackbar.error({
    //     visible: true,
    //     text: getErrorMessage(500, updateBankAccountErrorData?.error_code)
    //   })
    //   resetError(['updateBankAccountErrorData'])
    // }
    if (getBankAccountDetailsStatus === 'success') {
      setShowBottom(true)
      resetError(['getBankAccountDetailsStatus'])
    }
    if (getBankAccountDetailsErrorData) {
      setShowBottom(true)
      resetError(['getBankAccountDetailsErrorData'])
    }
  }, [getBankListRequest, updateBankAccountData?.operation_id, updateBankAccountStatus, updateBankAccountData?.bank_id, history, resetError, updateBankAccountErrorData, getBankAccountDetailsStatus, getBankAccountDetailsErrorData])

  const handleTogglePIC = useCallback(() => {
    setShowAgentPIC()
  }, [setShowAgentPIC])

  const handleCloseModal = useCallback(() => {
    setShowBottom(showBottom => !showBottom)
  }, [])

  // const handleDocChange = useCallback((data) => {
  //   setDocUrl(data.doc_url)
  //   setBtnEnable(!btnEnable)
  // }, [btnEnable])
  const bankList = bankLists?.getBankListData?.filter((item) => item.display_name !== 'GO-PAY')

  const formDataRef = useMemo(() =>
    [
      {
        type: 'autoSearchBottomSheet',
        name: 'bank_name',
        title: 'Nama Bank',
        required: true,
        data: {
          data: bankList,
          displayKey: 'bank_name',
          dataKey: 'bank_name'
        }
      },
      {
        type: 'number-hidden',
        name: 'account_number',
        title: 'Nomor Rekening',
        required: true
      },
      {
        type: 'number-hidden',
        name: 'repeat_account_number',
        title: 'Ulangi Nomor Rekening',
        validation: (value) => {
          return (`${value}`.toLowerCase() !== accountNumber)
        },
        hiddenIcon: true,
        error: ERROR_LANG.accountNumberMismatch,
        required: true
      }
      // {
      //   type: 'name',
      //   name: 'name',
      //   title: 'Nama Pemilik Rekening',
      //   validation: (value) => {
      //     return (`${value}`.toLowerCase() !== getAgentDetailData?.name.toLowerCase())
      //   },
      //   error: ERROR_LANG.wrongBankAccountName,
      //   required: true
      // },
      // {
      //   type: 'text',
      //   name: 'branch',
      //   title: 'Nama Bank Cabang',
      //   required: true
      // }
    ], [bankList, getAgentDetailData?.name])

  const handleChange = useCallback((data) => {
    if (data?.bank_name) {
      setBankID(data.bank_name.id)
    }
    if (data?.account_number) {
      setAccountNumber(data.account_number)
    }
    if (data?.repeat_account_number) {
      setRepeatAccountNumber(data.repeat_account_number)
    }
  }, [])

  const handleSubmit = () => {
    const formdata = formRef.current.validateFormValues()
    if (formdata) {
      if (formdata.repeat_account_number === ERROR_LANG.accountNumberMismatch && accountNumber !== repeatAccountNumber) {
        return
      }
      getBankAccountDetailsRequest({ holderId: accountNumber, query: { bank_code: bankCode } })
      setShowText(false)
    } else {
      setShowText(true)
    }
    // if (Object.values(formdata).indexOf(ERROR_LANG.wrongBankAccountName) > -1) {
    //   setShowBottom(true)
    //   return
    // }
    // setShowBottom(true)
    // handleSubmitForm()
  }

  const handleSubmitForm = useCallback(() => {
    updateBankAccountRequest({
      bank_code: bankCode,
      holder_id: accountNumber,
      holder_name: bankAccountData?.getBankAccountDetailsData?.holder_name
    })
  }, [updateBankAccountRequest, bankCode, accountNumber, bankAccountData])

  // const resetUrl = useCallback(() => {
  //   setDocUrl('')
  //   setBtnEnable(false)
  // }, [])

  return (
    <Container
      title={LANG_STRINGS.addBankAccount}
      displayBackButton
      hideBottomTabs
      className='bg-white'
      loader={GET_BANK_ACCOUNT_DETAILS_LOADER}
    >
      <AddBankWrapper>
        <DynamicForm
          form={formDataRef}
          onChange={data => handleChange(data)}
          ref={formRef}
        />
        {
          showText &&
            <CustomText
              className='help-text'
            >
              <p>{LANG_STRINGS.needHelpCustomerCare} <span className='click-text' onClick={handleTogglePIC}>disini</span></p>
            </CustomText>
        }
      </AddBankWrapper>
      <Footer>
        <Button className='submit-button' onClick={handleSubmit}>
          {LANG_STRINGS.saveNew}
        </Button>
      </Footer>
      {
        showBottom && (
          <BottomSheetVerify
            show={showBottom}
            onClose={handleCloseModal}
            onBankAdded={() => history.push('/bank-account')}
            handleSubmit={handleSubmitForm}
            data={bankAccountData?.getBankAccountDetailsData}
            bankList={bankList}
          />)
      }
    </Container>
  )
}

export default AddBankForm
