import { ConfigUrl } from '../../../../../../configs/url'

export const BANK_ACTIONS = {
  GET_BANK_ACCOUNT_LIST_REQUEST: 'GET_BANK_ACCOUNT_LIST_REQUEST',
  GET_BANK_ACCOUNT_LIST: 'GET_BANK_ACCOUNT_LIST',

  UPDATE_BANK_ACCOUNT_REQUEST: 'UPDATE_BANK_ACCOUNT_REQUEST',
  UPDATE_BANK_ACCOUNT: 'UPDATE_BANK_ACCOUNT',

  GET_BANK_ACCOUNT_DETAILS_REQUEST: 'GET_BANK_ACCOUNT_DETAILS_REQUEST',
  GET_BANK_ACCOUNT_DETAILS: 'GET_BANK_ACCOUNT_DETAILS',

  VERIFY_BANK_ACCOUNT_REQUEST: 'VERIFY_BANK_ACCOUNT_REQUEST',
  VERIFY_BANK_ACCOUNT: 'VERIFY_BANK_ACCOUNT',

  SEND_OTP_REQUEST: 'SEND_OTP_REQUEST',
  SEND_OTP: 'SEND_OTP',

  SET_POLICY_STATE: 'SET_POLICY_STATE',
  RESET_POLICY_STATE: 'RESET_POLICY_STATE',

  getBankAccountsList: (payload = {}) => {
    return {
      type: BANK_ACTIONS.GET_BANK_ACCOUNT_LIST_REQUEST,
      payload: {
        ...payload,
        method: 'GET',
        url: ConfigUrl.getBankListAccounts,
        query: payload,
      },
    }
  },
  setPolicyState: (payload) => ({
    type: BANK_ACTIONS.SET_POLICY_STATE,
    payload,
  }),
  resetPolicyState: (payload) => ({
    type: BANK_ACTIONS.RESET_POLICY_STATE,
    payload,
  }),
  getBankAccountDetails: (payload) => ({
    type: BANK_ACTIONS.GET_BANK_ACCOUNT_DETAILS_REQUEST,
    payload: {
      method: 'GET',
      query: {
        ...payload.query,
      },
      url: ConfigUrl.getBankAccountDetails(payload.holderId),
    },
  }),
  updateBankAccounts: (payload) => ({
    type: BANK_ACTIONS.UPDATE_BANK_ACCOUNT_REQUEST,
    payload: {
      body: payload,
      method: 'POST',
      url: ConfigUrl.updateBankListAccounts,
    },
  }),
  verifyBankAccounts: (payload) => ({
    type: BANK_ACTIONS.VERIFY_BANK_ACCOUNT_REQUEST,
    payload: {
      body: payload,
      method: 'POST',
      url: ConfigUrl.verifyBankAccounts,
    },
  }),
  sendOTP: (payload) => ({
    type: BANK_ACTIONS.SEND_OTP_REQUEST,
    payload: {
      body: payload,
      method: 'POST',
      url: ConfigUrl.sendOtp,
    },
  }),
}
