// import UploadFile from '../../../../../../../../components/DynamicForm/components/UploadFile'
import { BottomSheetVerifyContainerStyle } from './index.style'
import { useState, useEffect } from 'react'
import { LANG_STRINGS } from '../../../../../../../../lang'
import { Button, CustomText } from '../../../../../../../../components'
import { ACCOUNT_BANK, DELETE_WHITE, GREEN_CHECK_V2 } from '../../../../../../../../images'
import { AgentColorPallette } from '../../../../../../../../configs/colorPallete'
import { useErrorContextValue, useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import CircularLoader from '../../../../../../../../components/CircularLoader'
import ShowSnackbar from '../../../../../../../../components/ShowNotification'

function BottomSheetVerifyContainer ({ data = {}, bankList, onClose, onBankAdded, setIsBankAdded, handleSave }) {
  const [success, setSuccess] = useState(false)
  const [{ updateBankAccountStatus, updateBankAccountErrorData }] = useErrorContextValue()
  const { resetError } = useResetError()
  const [{ UPDATE_BANK_ACCOUNT_LOADER }] = useLoaderContextValue()

  const isNotEmptyObject = (obj) => obj && typeof obj === 'object' && !Array.isArray(obj) && Object.keys(obj).length > 0

  useEffect(() => {
    if (updateBankAccountStatus === 'success') {
      setSuccess(true)
      setIsBankAdded(true)
      resetError(['updateBankAccountErrorData', 'updateBankAccountStatus'])
    }
    if (updateBankAccountErrorData) {
      ShowSnackbar.error({
        visible: true,
        text: updateBankAccountStatus
      })
      resetError(['updateBankAccountErrorData', 'updateBankAccountStatus'])
    }
  }, [updateBankAccountStatus])

  return (
    <BottomSheetVerifyContainerStyle>
      <CircularLoader isLoading={UPDATE_BANK_ACCOUNT_LOADER}>
        {isNotEmptyObject(data) ? (
          !success ? (
            <>
              <div className='bank-info'>
                <img
                  src={ACCOUNT_BANK}
                  alt='information'
                  className='icon'
                />
                <CustomText
                  size='12px'
                  color={AgentColorPallette.black}
                  weight='700'
                  className=''
                  textAlign='center'
                >
                  {bankList.find(item => item.bank_code === data?.bank_code)?.bank_name}
                </CustomText>
                <CustomText
                  size='16px'
                  color={AgentColorPallette.black}
                  weight='700'
                  className=''
                  textAlign='center'
                >
                  {data?.holder_name}
                </CustomText>
                <CustomText
                  size='12px'
                  color={AgentColorPallette.black}
                  className='bottom-text'
                  textAlign='center'
                >
                  {data?.holder_id}
                </CustomText>
              </div>
              <div className='flex-container box'>
                <CustomText
                  size='12px'
                  color={AgentColorPallette.black}
                  className='text'
                  textAlign='center'
                >
                  Pastikan semua data diatas sudah benar
                </CustomText>
              </div>
              <Button onClick={handleSave} className='submit-button' textColor='#000000'>
                {LANG_STRINGS.save}
              </Button>
              <Button onClick={onClose} className='submit-button' backgroundColor='#FFFFFF' textColor='#000000'>
                {LANG_STRINGS.return}
              </Button>
            </>
          ) : (
            <div className='align-center'>
              <img
                src={GREEN_CHECK_V2}
                alt='check'
                className='icon'
              />
              <CustomText
                size='12px'
                color={AgentColorPallette.black}
                weight='700'
                className=''
                bottom='20px'
                textAlign='center'
              >
                Akun bank berhasil ditambah
              </CustomText>
              <Button className='submit-button' onClick={onBankAdded} textColor='#000000'>
                {LANG_STRINGS.okay}
              </Button>
            </div>
          )
        ) : (
          <div className='align-center'>
            <img
              src={DELETE_WHITE}
              alt='cross'
              className='icon'
            />
            <CustomText
              size='12px'
              color={AgentColorPallette.black}
              weight='700'
              className=''
              bottom='20px'
              textAlign='center'
            >
              Akun bank tidak ditemukan
            </CustomText>
            <Button className='submit-button' onClick={onBankAdded} textColor='#000000'>
              {LANG_STRINGS.okay}
            </Button>
          </div>
        )}
      </CircularLoader>
    </BottomSheetVerifyContainerStyle>
  )
}
export default BottomSheetVerifyContainer
