import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useCallback } from 'react'
import { useBankAccountContextValue } from '../../context'
import { BANK_ACTIONS } from '../actions'

export const useBankServiceCall = (actionsCall = () => {}) => {
  const [withdrawalState, dispatch] = useBankAccountContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = useCallback((payload = {}) => {
    callApi(actionsCall({
      ...payload
    }))
  }, [callApi, actionsCall])
  return [withdrawalState, request]
}

export const useGetBankAccountList = () => {
  return useBankServiceCall(BANK_ACTIONS.getBankAccountsList)
}

export const useUpdateBankAccounts = () => {
  return useBankServiceCall(BANK_ACTIONS.updateBankAccounts)
}

export const useGetBankAccountDetails = () => {
  return useBankServiceCall(BANK_ACTIONS.getBankAccountDetails)
}

export const useVerifyBankAccounts = () => {
  return useBankServiceCall(BANK_ACTIONS.verifyBankAccounts)
}

export const useSendOtp = () => {
  return useBankServiceCall(BANK_ACTIONS.sendOTP)
}
