import BottomActionSheet from '../../../../../../../components/BottomActionSheet'
import BottomSheetSelectContainer from './container'
import { useState } from 'react'
import { LANG_STRINGS } from '../../../../../../../lang/index'

function BottomSheetVerify ({ show, data, bankList, onClose, onBankAdded, handleSubmit }) {
  const [isBankAdded, setIsBankAdded] = useState(false)
  const isNotEmptyObject = (obj) => obj && typeof obj === 'object' && !Array.isArray(obj) && Object.keys(obj).length > 0

  return (
    <BottomActionSheet
      show={show}
      title={LANG_STRINGS.verificationBank}
      onCloseSheet={isNotEmptyObject(data) && !isBankAdded ? onClose : onBankAdded}
      showHeader
    >
      <BottomSheetSelectContainer
        data={data}
        bankList={bankList}
        onClose={onClose}
        onBankAdded={onBankAdded}
        setIsBankAdded={setIsBankAdded}
        handleSave={handleSubmit}
      />
    </BottomActionSheet>
  )
}

export default BottomSheetVerify
