import { WITHDRAWAL_ACTIONS } from './actions'

const reducer = (state = WITHDRAWAL_ACTIONS, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case WITHDRAWAL_ACTIONS.GET_WITHDRAWAL_LIST:
      return {
        ...state,
        ...payload
      }
    case WITHDRAWAL_ACTIONS.GET_BANK_LIST:
    case WITHDRAWAL_ACTIONS.BANK_WITHDRAW:
      return {
        ...state,
        ...payload
      }
    default:
      return {
        ...(state || {})
      }
  }
}

export default reducer

